1	// Fake DOM + controllable fetch for running public/app.js in node:vm.
2	// Every object handed to the script is a Proxy that records any member outside the
3	// spec's allowed list in `page.forbidden`, so tests can assert only allowed APIs were used.
4	import { readFileSync } from 'node:fs';
5	import vm from 'node:vm';
6	
7	export const APP_PATH = new URL('../../public/app.js', import.meta.url);
8	const ELEMENT_MEMBERS = new Set(['textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren', 'addEventListener']);
9	const DOCUMENT_MEMBERS = new Set(['getElementById', 'createElement']);
10	const REPLY_MEMBERS = new Set(['status', 'json']);
11	const EVENT_MEMBERS = new Set(['preventDefault']);
12	const BROWSER_GLOBALS = ['window', 'self', 'console', 'setTimeout', 'setInterval', 'queueMicrotask', 'requestAnimationFrame',
13	  'XMLHttpRequest', 'location', 'navigator', 'alert', 'localStorage', 'sessionStorage', 'Headers', 'Request', 'Response',
14	  'URL', 'URLSearchParams', 'Event', 'CustomEvent', 'structuredClone', 'addEventListener'];
15	// The page's elements: id -> [tag, type].
16	const PAGE_ELEMENTS = {
17	  'booking-form': ['form'], room: ['select'], title: ['input', 'text'], date: ['input', 'date'],
18	  start: ['input', 'time'], end: ['input', 'time'], book: ['button', 'submit'], 'filter-date': ['input', 'date'],
19	  'show-all': ['button', 'button'], 'booking-list': ['ul'], error: ['p'],
20	};
21	
22	/** A text node made by `append(string)`. */
23	export class TextNode {
24	  constructor(data) { this.data = String(data); }
25	}
26	
27	/** Minimal element: children, textContent, value, type, disabled, listeners. */
28	export class FakeElement {
29	  constructor(page, tag, id) {
30	    this.page = page;
31	    this.tagName = tag;
32	    this.id = id;
33	    this.childNodes = [];
34	    this.listeners = {};
35	    this.attrs = { value: '', type: undefined, disabled: false };
36	  }
37	  get textContent() {
38	    return this.childNodes.map((n) => (n instanceof TextNode ? n.data : n.textContent)).join('');
39	  }
40	  set textContent(text) {
41	    this.page.log.push({ id: this.id, prop: 'textContent', value: String(text), bookDisabled: this.page.bookDisabled() });
42	    this.childNodes = String(text) === '' ? [] : [new TextNode(text)];
43	  }
44	  get value() { return this.tagName === 'select' ? this.selectValue() : this.attrs.value; }
45	  set value(v) {
46	    this.page.log.push({ id: this.id, prop: 'value', value: String(v), bookDisabled: this.page.bookDisabled() });
47	    if (this.tagName === 'select') this.selectedValue = String(v);
48	    else this.attrs = { ...this.attrs, value: String(v) };
49	  }
50	  get type() { return this.attrs.type; }
51	  set type(v) { this.attrs = { ...this.attrs, type: String(v) }; }
52	  get disabled() { return this.attrs.disabled; }
53	  set disabled(v) { this.attrs = { ...this.attrs, disabled: Boolean(v) }; }
54	  selectValue() {
55	    if (this.selectedValue !== undefined) return this.selectedValue;
56	    const first = this.childNodes.find((n) => n instanceof FakeElement && n.tagName === 'option');
57	    return first ? first.value : '';
58	  }
59	  append(...nodes) {
60	    this.childNodes = [...this.childNodes, ...nodes.map((n) => (typeof n === 'string' ? new TextNode(n) : unwrap(n)))];
61	  }
62	  replaceChildren(...nodes) {
63	    this.page.log.push({ id: this.id, prop: 'replaceChildren', value: nodes.length, bookDisabled: this.page.bookDisabled() });
64	    this.childNodes = nodes.map((n) => (typeof n === 'string' ? new TextNode(n) : unwrap(n)));
65	  }
66	  addEventListener(type, handler) {
67	    this.listeners = { ...this.listeners, [type]: [...(this.listeners[type] ?? []), handler] };
68	  }
69	  /** Test side: fires an event; returns { defaultPrevented }. */
70	  dispatch(type) {
71	    const state = { defaultPrevented: false };
72	    const event = guard(this.page, 'event', { preventDefault() { state.defaultPrevented = true; } }, EVENT_MEMBERS);
73	    (this.listeners[type] ?? []).forEach((handler) => handler.call(this.proxy, event));
74	    return state;
75	  }
76	}
77	
78	const RAW = Symbol('raw');
79	function unwrap(node) { return node?.[RAW] ?? node; }
80	
81	function guard(page, kind, target, allowed) {
82	  return new Proxy(target, {
83	    get(obj, key) {
84	      if (key === RAW) return obj;
85	      // `then` is probed by the engine when a reply resolves a promise; not a script access.
86	      const engineProbe = kind === 'reply' && key === 'then';
87	      if (typeof key === 'string' && !allowed.has(key) && !engineProbe) page.forbidden.push(`${kind}.${key}`);
88	      const value = Reflect.get(obj, key, obj);
89	      return typeof value === 'function' ? value.bind(obj) : value;
90	    },
91	    set(obj, key, value) {
92	      if (typeof key === 'string' && !allowed.has(key)) page.forbidden.push(`${kind}.${key}=`);
93	      return Reflect.set(obj, key, value, obj);
94	    },
95	  });
96	}
97	
98	function makeElement(page, tag, id) {
99	  const element = new FakeElement(page, tag, id);
100	  element.proxy = guard(page, `<${tag}>`, element, ELEMENT_MEMBERS);
101	  return element;
102	}
103	
104	/** One fetch call the test can settle: respond(), respondSlowJson(), respondUnparseable(), fail(). */
105	class FetchCall {
106	  constructor(page, url, options) {
107	    this.page = page;
108	    this.url = url;
109	    this.options = options;
110	    this.jsonCalls = 0;
111	    this.bookDisabledAtCall = page.bookDisabled();
112	    this.promise = new Promise((resolve, reject) => { this.resolve = resolve; this.reject = reject; });
113	  }
114	  reply(status, json) {
115	    const call = this;
116	    const target = { status, json() { call.jsonCalls += 1; return json(); } };
117	    this.resolve(guard(this.page, 'reply', target, REPLY_MEMBERS));
118	  }
119	  /** Settles with `status` and a body that json() parses (a fresh copy each time). */
120	  respond(status, body) {
121	    const text = JSON.stringify(body);
122	    this.reply(status, () => Promise.resolve(JSON.parse(text)));
123	  }
124	  /** Settles the status now; json() stays pending until the returned resolveJson(body) is called. */
125	  respondSlowJson(status) {
126	    let resolveJson;
127	    const pending = new Promise((resolve) => { resolveJson = resolve; });
128	    this.reply(status, () => pending);
129	    return (body) => resolveJson(JSON.parse(JSON.stringify(body)));
130	  }
131	  /** Settles with `status` and a body whose json() rejects (unparseable). */
132	  respondUnparseable(status) {
133	    this.reply(status, () => Promise.reject(new SyntaxError('Unexpected token')));
134	  }
135	  /** No reply at all: fetch rejects. */
136	  fail() { this.reject(new TypeError('Failed to fetch')); }
137	}
138	
139	/** Runs app.js against a fresh fake page. Returns the page handle used by tests. */
140	export function loadApp({ source = readFileSync(APP_PATH, 'utf8') } = {}) {
141	  const page = { forbidden: [], log: [], calls: [], elements: {} };
142	  page.bookDisabled = () => page.elements.book?.attrs.disabled ?? false;
143	  Object.entries(PAGE_ELEMENTS).forEach(([id, [tag, type]]) => {
144	    const element = makeElement(page, tag, id);
145	    element.attrs = { ...element.attrs, type };
146	    page.elements[id] = element;
147	  });
148	  page.created = [];
149	  const document = guard(page, 'document', {
150	    getElementById: (id) => page.elements[id]?.proxy ?? null,
151	    createElement: (tag) => {
152	      const element = makeElement(page, String(tag).toLowerCase(), undefined);
153	      page.created.push(element);
154	      return element.proxy;
155	    },
156	  }, DOCUMENT_MEMBERS);
157	  const fetch = (url, options) => {
158	    const call = new FetchCall(page, url, options);
159	    page.calls.push(call);
160	    return call.promise;
161	  };
162	  const sandbox = { document, fetch };
163	  BROWSER_GLOBALS.forEach((name) => {
164	    Object.defineProperty(sandbox, name, { get() { page.forbidden.push(`global.${name}`); return undefined; } });
165	  });
166	  vm.createContext(sandbox);
167	  vm.runInContext(source, sandbox, { filename: 'app.js' });
168	  return page;
169	}
170	
171	/** Lets pending promise chains in the script run to completion. */
172	export async function flush(rounds = 10) {
173	  for (let i = 0; i < rounds; i += 1) await new Promise((resolve) => setImmediate(resolve));
174	}
175	
176	/** Describes an element's children for exact assertions: strings for text nodes, elements as-is. */
177	export function childSummary(element) {
178	  return element.childNodes.map((n) => (n instanceof TextNode ? { text: n.data } : { tag: n.tagName, type: n.type, text: n.textContent }));
179	}
180	
181	/** Booking fixture. */
182	export function booking(overrides = {}) {
183	  return { id: 1, room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides };
184	}
185	
186	/**
187	 * Loads the app and settles the two startup fetches: rooms with the three rooms,
188	 * the list with `bookings`. Returns the page with no pending calls.
189	 */
190	export async function loadReadyApp(bookings = []) {
191	  const page = loadApp();
192	  await flush();
193	  page.calls.find((c) => c.url === '/api/rooms').respond(200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
194	  page.calls.find((c) => c.url === '/api/bookings').respond(200, { bookings });
195	  await flush();
196	  return page;
197	}
198	
199	/** The Cancel button elements currently in the list, in order. */
200	export function cancelButtons(page) {
201	  return page.elements['booking-list'].childNodes.flatMap((li) => li.childNodes.filter((n) => n instanceof FakeElement && n.tagName === 'button'));
202	}
