1	// Tiny HTML parser for tests: tags, attributes and text only.
2	const VOID = new Set('area base br col embed hr img input link meta source track wbr'.split(' '));
3	const RAW = new Set(['script', 'style', 'title', 'textarea']);
4	const ATTR_RE = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/y;
5	
6	function parseAttrs(src) {
7	  const attrs = {};
8	  let pos = 0;
9	  while (pos < src.length) {
10	    if (/[\s\/]/.test(src[pos])) { pos++; continue; }
11	    ATTR_RE.lastIndex = pos;
12	    const m = ATTR_RE.exec(src);
13	    if (!m) { pos++; continue; }
14	    attrs[m[1].toLowerCase()] = m[2] ?? m[3] ?? m[4] ?? '';
15	    pos = ATTR_RE.lastIndex;
16	  }
17	  return attrs;
18	}
19	
20	function closeTag(text, i, root, cur) {
21	  const end = text.indexOf('>', i);
22	  const name = text.slice(i + 2, end < 0 ? text.length : end).trim().toLowerCase();
23	  let next = cur;
24	  for (let n = cur; n && n !== root; n = n.parent) {
25	    if (n.tag === name) { next = n.parent; break; }
26	  }
27	  return { cur: next, i: end < 0 ? text.length : end + 1 };
28	}
29	
30	function openTag(text, i, cur) {
31	  const m = /^<([a-zA-Z][^\s\/>]*)((?:"[^"]*"|'[^']*'|[^'">])*)>/.exec(text.slice(i));
32	  if (!m) return null;
33	  const tag = m[1].toLowerCase();
34	  const node = { tag, attrs: parseAttrs(m[2]), children: [], parent: cur };
35	  cur.children.push(node);
36	  i += m[0].length;
37	  if (VOID.has(tag)) return { cur, i };
38	  if (!RAW.has(tag)) return { cur: node, i };
39	  const close = new RegExp('</' + tag + '\\s*>', 'i').exec(text.slice(i));
40	  const stop = close ? i + close.index : text.length;
41	  if (stop > i) node.children.push({ text: text.slice(i, stop), parent: node });
42	  return { cur, i: close ? stop + close[0].length : text.length };
43	}
44	
45	export function parseHtml(text) {
46	  const root = { tag: '#root', attrs: {}, children: [], parent: null };
47	  let cur = root;
48	  let i = 0;
49	  const addText = (t) => { if (t) cur.children.push({ text: t, parent: cur }); };
50	  while (i < text.length) {
51	    const lt = text.indexOf('<', i);
52	    if (lt < 0) { addText(text.slice(i)); break; }
53	    addText(text.slice(i, lt));
54	    i = lt;
55	    if (text.startsWith('<!--', i)) {
56	      const end = text.indexOf('-->', i + 4);
57	      i = end < 0 ? text.length : end + 3;
58	    } else if (text.startsWith('<!', i) || text.startsWith('<?', i)) {
59	      const end = text.indexOf('>', i);
60	      i = end < 0 ? text.length : end + 1;
61	    } else if (text.startsWith('</', i)) {
62	      ({ cur, i } = closeTag(text, i, root, cur));
63	    } else {
64	      const r = openTag(text, i, cur);
65	      if (!r) { addText('<'); i++; } else { cur = r.cur; i = r.i; }
66	    }
67	  }
68	  return root;
69	}
70	
71	export function findAll(root, predicate) {
72	  const out = [];
73	  const walk = (n) => {
74	    for (const c of n.children ?? []) {
75	      if (c.tag === undefined) continue;
76	      if (predicate(c)) out.push(c);
77	      walk(c);
78	    }
79	  };
80	  walk(root);
81	  return out;
82	}
83	
84	export const byId = (root, id) => findAll(root, (n) => n.attrs.id === id)[0] ?? null;
85	
86	export function textOf(node) {
87	  if (node.text !== undefined) return node.text;
88	  return (node.children ?? []).map(textOf).join('');
89	}
90	
91	export function isDescendant(node, ancestor) {
92	  for (let n = node.parent; n; n = n.parent) if (n === ancestor) return true;
93	  return false;
94	}
95	
96	export const elementChildren = (node) => node.children.filter((c) => c.tag !== undefined);
