1	// Startup behaviour of server.mjs: PORT, DATA_FILE, listening line, order of checks.
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import net from 'node:net';
5	import { existsSync } from 'node:fs';
6	import { mkdir, readFile, writeFile } from 'node:fs/promises';
7	import { join } from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	import {
10	  makeTempDir, removeDir, runUntilExit, startServer, request, postBooking, validBooking,
11	} from './helpers/server-harness.mjs';
12	
13	const REPO_DIR = fileURLToPath(new URL('..', import.meta.url)).replace(/\/$/, '');
14	
15	/** Runs fn(tmpDir) in a fresh temp dir and always removes it. */
16	async function withTemp(fn) {
17	  const dir = await makeTempDir();
18	  try {
19	    return await fn(dir);
20	  } finally {
21	    await removeDir(dir);
22	  }
23	}
24	
25	/** Runs fn(server) and always stops the server. */
26	async function withServer(options, fn) {
27	  const server = await startServer(options);
28	  try {
29	    return await fn(server);
30	  } finally {
31	    await server.stop();
32	  }
33	}
34	
35	function assertOneStderrLineExit1(result) {
36	  assert.equal(result.code, 1);
37	  assert.equal(result.stdout, '');
38	  assert.match(result.stderr, /^[^\n]+\n$/);
39	  assert.equal(result.stderr.includes('    at '), false);
40	}
41	
42	function listenOn(port) {
43	  return new Promise((resolve, reject) => {
44	    const blocker = net.createServer();
45	    blocker.once('error', reject);
46	    blocker.listen(port, '127.0.0.1', () => resolve(blocker));
47	  });
48	}
49	
50	function closeServer(blocker) {
51	  return new Promise((resolve) => blocker.close(resolve));
52	}
53	
54	async function freePort() {
55	  const blocker = await listenOn(0);
