73	/** Bytes of `obj` as JSON padded with spaces inside the object to exactly `size` bytes. */
74	function paddedBody(obj, size) {
75	  const json = JSON.stringify(obj);
76	  const pad = size - Buffer.byteLength(json);
77	  assert.ok(pad >= 0);
78	  const text = '{' + ' '.repeat(pad) + json.slice(1);
