83	/** Body with an ignored "pad" key of 'é' (2 bytes each) plus spaces, exactly `size` bytes. */
84	function accentBody(obj, size) {
85	  const base = Buffer.byteLength(JSON.stringify({ ...obj, pad: '' }));
86	  const count = Math.floor((size - base) / 2);
87	  const text = JSON.stringify({ ...obj, pad: 'é'.repeat(count) });
88	  const full = ' '.repeat(size - Buffer.byteLength(text)) + text;
89	  assert.equal(Buffer.byteLength(full), size);
90	  return { buffer: Buffer.from(full), text: full };
91	}
